(5899750, 858942, 104198, '<td valign="top">A nice photo with shadows included, but it seems to be more of a "reflective" shot to my eyes.</td>', 'A nice photo with shadows included, but it seems to be more of a "reflective" shot to my eyes.', '2010-03-11 08:43:54.000000', NULL, 1),
(5899777, 858434, 104230, '<td valign="top">Wonderful sense of movement in this image, and it almost has the feeling of a wood cut/etching. Great composition and contrast. Love it! 9</td>', 'Wonderful sense of movement in this image, and it almost has the feeling of a wood cut/etching. Great composition and contrast. Love it! 9', '2010-03-11 09:17:20.000000', NULL, 1),
(5899785, 858963, 104230, '<td valign="top">An interesting concept, but this does not engage me at all emotionally.  The most prominent part of the image is the metal socket thread, but that is the least interesting thing and also at odds with the focus you want given your title. 5</td>', 'An interesting concept, but this does not engage me at all emotionally.  The most prominent part of the image is the metal socket thread, but that is the least interesting thing and also at odds with the focus you want given your title. 5', '2010-03-11 09:27:50.000000', NULL, 1),
