(5899999, 859148, 12733, '<td valign="top">A very interesting idea and execution. Too bad you couldn''t get rid of the distracting vent, or whatever it is, in the lower left corner.</td>', 'A very interesting idea and execution. Too bad you couldn''t get rid of the distracting vent, or whatever it is, in the lower left corner.', '2010-03-11 12:36:34.000000', NULL, 1),
(5900002, 859720, 12733, '<td valign="top">Nice texture on the stone and steel, but the essence of a shadow is it doesn''t reveal texture. I think the shadows play too small a role in this picture.</td>', 'Nice texture on the stone and steel, but the essence of a shadow is it doesn''t reveal texture. I think the shadows play too small a role in this picture.', '2010-03-11 12:38:21.000000', NULL, 1),
(5900004, 859582, 12733, '<td valign="top">It''s the colors that make this photo, not the shadows. I particularly like the muted colors on the far wall, but again, that wasn''t the point of this challenge.</td>', 'It''s the colors that make this photo, not the shadows. I particularly like the muted colors on the far wall, but again, that wasn''t the point of this challenge.', '2010-03-11 12:40:41.000000', NULL, 1),
